// 语义缓存 + 模型路由（示意）
public String answer(String q) {
    String exact = redis.opsForValue().get("ans:" + DigestUtils.md5Hex(q));
    if (exact != null) return exact;                                   // 精确缓存

    List<Document> hits = cacheStore.similaritySearch(SearchRequest.builder()
            .query(q).topK(1).similarityThreshold(0.95).build());       // 语义缓存，阈值要高
    if (!hits.isEmpty()) return (String) hits.get(0).getMetadata().get("answer");

    ChatClient model = classifier.isSimple(q) ? smallModel : largeModel; // 模型路由
    String ans = model.prompt().user(q)
            .options(ChatOptions.builder().maxTokens(500).build())       // 限制输出
            .call().content();
    redis.opsForValue().set("ans:" + DigestUtils.md5Hex(q), ans, Duration.ofHours(12));
    return ans;
}

